<section class="saas-card"><h2>تقویم‌های تصمیم‌گیری‌شده و محتوای نهایی</h2><a href="/panel/task_manager.php?project=<?=rawurlencode($pid)?>">کارتابل تسک‌های پروژه</a><?php foreach($calendars as $plan):?><details class="saas-project"><summary><?=ar_h($plan['start'].' تا '.$plan['end'].' / '.ar_state($plan['state']))?></summary><?php if($manage&&$plan['state']==='approved'):?><form method="post"><input type="hidden" name="action" value="calendar_pause"><input type="hidden" name="plan" value="<?=ar_h($plan['id'])?>"><button>تأیید توقف تقویم برای بازبینی</button></form><?php endif;?><?php foreach($plan['entries'] as $item):$canEdit=$use&&($manage||in_array($_SESSION['user']['username'],[$item['roles']['writer'],$item['roles']['designer']],true));$canReview=$use&&($manage||$item['roles']['reviewer']===$_SESSION['user']['username']);?><article class="aria-slot"><h3><?=ar_h($item['title'])?></h3><p><?=ar_h(Aria::CHANNELS[$item['channel']].' / '.$item['publish_at'])?></p><span class="nahal-status"><?=ar_h(ar_state($item['state']))?></span><p>متن: <?=ar_h($item['roles']['writer']??'نیازمند تعیین مسئول')?> · طراحی: <?=ar_h($item['roles']['designer']??'نیازمند تعیین مسئول')?> · تأیید: <?=ar_h($item['roles']['reviewer']??'نیازمند تعیین مسئول')?></p><p>مسیر انتشار: <?=ar_h(['direct'=>'ارسال مستقیم با رسید واقعی','external_chatgpt'=>'ابزار متصل ChatGPT؛ صف به معنای انتشار نیست','connection_required'=>'اتصال لازم است','website_publish_adapter_required'=>'آداپتور انتشار محتوای جدید وب‌سایت هنوز متصل نیست','rubika_contract_required'=>'قرارداد انتشار روبیکا هنوز تأیید نشده','sms_recipient_cost_approval_required'=>'نیازمند تأیید مستقل گیرندگان و قیمت پیامک'][AriaPublisher::capability($p,$item['channel'])]??'نامشخص')?></p><?php if(!empty($item['receipt'])):?><pre><?=ar_h(json_encode($item['receipt'],JSON_UNESCAPED_UNICODE))?></pre><?php endif;?><?php if($canEdit&&$plan['state']==='approved'&&!in_array($item['state'],['dispatching','published','queued_external','uncertain'],true)):?><form method="post"><input type="hidden" name="action" value="content"><input type="hidden" name="plan" value="<?=ar_h($plan['id'])?>"><input type="hidden" name="entry" value="<?=ar_h($item['id'])?>"><input type="hidden" name="revision" value="<?=(int)$item['revision']?>"><label>متن نهایی انسانی<textarea name="caption" maxlength="20000" rows="4" required><?=ar_h($item['caption']??'')?></textarea></label><label>لینک HTTPS تصویر آماده<input type="url" name="media" value="<?=ar_h($item['media']??'')?>" dir="ltr"></label><button>ثبت نسخهٔ محتوا</button></form><?php endif;?><?php if($canReview&&$item['state']==='awaiting_approval'):?><form method="post"><input type="hidden" name="action" value="content_decision"><input type="hidden" name="plan" value="<?=ar_h($plan['id'])?>"><input type="hidden" name="entry" value="<?=ar_h($item['id'])?>"><input type="hidden" name="revision" value="<?=(int)$item['revision']?>"><input type="hidden" name="hash" value="<?=ar_h($item['content_hash'])?>"><button name="decision" value="approve">تأیید همین نسخه برای انتشار</button><button name="decision" value="reject">درخواست اصلاح محتوا</button></form><?php endif;?><?php if($manage&&$item['image_brief']&&$plan['state']==='approved'):?><form method="post"><input type="hidden" name="action" value="nahal"><input type="hidden" name="plan" value="<?=ar_h($plan['id'])?>"><input type="hidden" name="entry" value="<?=ar_h($item['id'])?>"><button>ارجاع تصویر به نهال با بررسی هزینه</button></form><?php endif;?></article><?php endforeach;?></details><?php endforeach;?></section>
<?php if($manage):?><section class="saas-card" id="sms"><h2>اتصال پیامک همین پروژه</h2><p>نجوا و ملی‌پیامک مستقل از اعتبار AI هستند. رمزها نمایش داده نمی‌شوند. ذخیرهٔ اطلاعات، به معنی اتصال موفق نیست.</p><div class="saas-grid"><?php foreach(['melipayamak'=>'ملی‌پیامک','najva'=>'نجوا'] as $provider=>$label):$connection=$connections[$provider]??[];?><article class="saas-project"><h3><?=$label?></h3><form method="post"><input type="hidden" name="action" value="sms_save"><input type="hidden" name="provider" value="<?=$provider?>"><label>نام کاربری<input name="username" value="<?=ar_h($connection['username']??'')?>" <?=$provider==='melipayamak'?'required':''?>></label><label>خط ارسال<input name="sender" dir="ltr" value="<?=ar_h($connection['sender']??'')?>" required></label><label><?=$provider==='melipayamak'?'رمز API':'توکن API'?>؛ خالی برای حفظ قبلی<input type="password" name="secret" autocomplete="new-password"></label><button>ذخیرهٔ امن اتصال</button></form><?php if($provider==='melipayamak'):?><form method="post"><input type="hidden" name="action" value="sms_probe"><input type="hidden" name="provider" value="<?=$provider?>"><button <?=!$connection?'disabled':''?>>استعلام حساب و اعتبار ملی‌پیامک</button></form><?php if(isset($connection['probe'])):$probe=$connection['probe'];?><p><?=$probe['success']?'پاسخ استعلام دریافت شد':'استعلام ناموفق'?> · <?=formatPersianDate($probe['at'],'Y/m/d H:i')?></p><p>اعتبار اعلام‌شده به تعداد پیامک: <?=ar_h($probe['balance']??'نامشخص')?> · نرخ پایهٔ اعلام‌شده: <?=ar_h($probe['base_price']??'نامشخص')?></p><p>اعتبار حساب بر حسب تعداد پیامک است؛ نرخ پایه، قیمت قطعی کل کمپین نیست. قیمت کل را از پنل سرویس‌دهنده برای همین متن و گیرندگان بررسی کنید.</p><?php endif;?><?php else:?><p>اطلاعات قابل ذخیره است؛ ارسال کمپین از API رسمی نسخهٔ ۲ انجام می‌شود؛ در مستندات ارائه‌شده رابط استعلام موجودی و قیمت پیش از ارسال مشخص نشده است. قیمت هر کمپین باید با مرجع پنل نجوا ثبت و جداگانه تأیید شود.</p><?php endif;?></article><?php endforeach;?></div>
<h3>پیش‌نمایش کمپین پیامکی</h3><p>شماره‌های تکراری حذف می‌شوند. قیمت کل را از پنل سرویس‌دهنده ثبت و سپس متن، تعداد و هزینه را تأیید کنید؛ انتشار خودکار این شرط را دور نمی‌زند.</p><form method="post"><input type="hidden" name="action" value="sms_preview"><input type="hidden" name="request_id" value="<?=bin2hex(random_bytes(16))?>"><label>سرویس<select name="provider"><option value="melipayamak">ملی‌پیامک</option><option value="najva">نجوا</option></select></label><label>متن پیامک<textarea name="text" maxlength="3000" required></textarea></label><label>گیرندگان؛ هر شماره در یک خط<textarea name="recipients" maxlength="30000" dir="ltr" required></textarea></label><button>ثبت متن و محاسبهٔ گیرندگان یکتا</button></form><?php foreach(array_slice($sms->campaigns($p),0,15) as $campaign):?><article class="saas-project"><p><?=ar_h($campaign['provider'])?> · <?=(int)$campaign['count']?> گیرندهٔ یکتا · هزینه: <?=ar_h($campaign['cost']??'در انتظار استعلام واقعی')?> · <?=ar_h(['awaiting_provider_quote'=>'در انتظار قیمت','quoted'=>'در انتظار تأیید هزینه','sending'=>'در حال ارسال / تکرار نکنید','accepted'=>'پذیرفته‌شده توسط سرویس؛ تحویل تأیید نشده','failed'=>'ناموفق','uncertain'=>'نتیجه نامشخص؛ تکرار نکنید'][$campaign['state']]??$campaign['state'])?></p><p><?=nl2br(ar_h($campaign['text']))?></p><?php if(in_array($campaign['state'],['awaiting_provider_quote','quoted'],true)):?><?php if($campaign['provider']==='melipayamak'):?><form method="post"><input type="hidden" name="action" value="sms_api_quote"><input type="hidden" name="campaign" value="<?=ar_h($campaign['id'])?>"><p>استعلام API قیمت به تعداد واقعی گیرندگان هر اپراتور نیاز دارد؛ شمارهٔ پیش‌شماره به‌تنهایی با وجود ترابرد کافی نیست.</p><label>تعداد ایرانسل<input type="number" name="irancell" min="0" max="1000" required></label><label>تعداد همراه اول<input type="number" name="mtn" min="0" max="1000" required></label><button>استعلام قیمت کل از API ملی‌پیامک</button></form><?php endif;?><form method="post"><input type="hidden" name="action" value="sms_quote"><input type="hidden" name="campaign" value="<?=ar_h($campaign['id'])?>"><label>قیمت کل همین کمپین از پنل سرویس‌دهنده؛ ریال<input type="number" name="amount" min="1" max="10000000000" required></label><label>مرجع قیمت؛ شمارهٔ پیش‌فاکتور یا توضیح استعلام پنل<input name="reference" maxlength="300" required></label><p>ثبت دستی توسط ادمین؛ استعلام API یا تضمین هزینهٔ نهایی محسوب نمی‌شود. تعرفهٔ معتبر سرویس‌دهنده را برای متن و همین گیرندگان بررسی کنید.</p><button>ثبت قیمت برای بررسی</button></form><?php endif;?><?php if($campaign['state']==='quoted'):?><form method="post"><input type="hidden" name="action" value="sms_send"><input type="hidden" name="campaign" value="<?=ar_h($campaign['id'])?>"><input type="hidden" name="quote_hash" value="<?=ar_h($campaign['quote_hash'])?>"><input type="hidden" name="count" value="<?=(int)$campaign['count']?>"><input type="hidden" name="amount" value="<?=(int)$campaign['cost']?>"><p><?=($campaign['quote_source']??'')==='provider_api_declared_operator_counts'?'قیمت API براساس تعداد اپراتور اعلام‌شده':'قیمت ثبت‌شده توسط ادمین'?>: <?=number_format($campaign['cost'])?> ریال · <?=ar_h($campaign['quote_reference'])?> · اعتبار تأیید تا <?=formatPersianDate($campaign['quote_expires'],'H:i')?></p><label class="saas-toggle"><input type="checkbox" name="confirmed" required>متن بالا، <?=(int)$campaign['count']?> گیرنده و هزینهٔ ثبت‌شده را بررسی کرده‌ام و ارسال واقعی را تأیید می‌کنم.</label><button>تأیید هزینه و ارسال واقعی همین کمپین</button></form><?php endif;?></article><?php endforeach;?></section><?php endif;?></main></body></html>
